"""Render publication report and unposted maintainer comment from audited stats.

Interpretation text is frozen in interpretation.json after examining all cells.
All primary numerical tables come directly from regenerated raw-pair summary.
"""
import csv,datetime,json,math,pathlib,statistics,time
import run
C=run.C
def pct(x):return f'{100*(x-1):+.2f}%'
def prose_spaces(text):
 # Presentation-only corrections; never alter hashes, file paths or raw tables.
 replacements={'issue921':'issue #921','default20ms':'default 20 ms','100µs':'100 µs','20ms':'20 ms','10+pair':'10+ pair','sixAB/sixBA':'six AB/six BA','sixAB':'six AB','sixBA':'six BA','fiveAB/fiveBA':'five AB/five BA','two-sided95%':'two-sided 95%','paired95%':'paired 95%','sixteenCPU':'sixteen CPU','2 AB/2 BA':'2 AB/2 BA','2/2 within':'2/2 within','first10':'first 10','full12':'full 12','Each12-pair':'Each 12-pair','12-pair':'12-pair','GGMLpin':'GGML pin','BinarySHA256':'Binary SHA256','LinuxCUDA':'Linux CUDA','HIPMMQ':'HIP MMQ','runtimeCUDA':'runtime CUDA','CUDApeer':'CUDA peer','dualRTX':'dual RTX','RTX4090':'RTX 4090','Ryzen97950X3D':'Ryzen 9 7950X3D','16guestvCPUs':'16 guest vCPUs','16guest':'16 guest','16vCPUs':'16 vCPUs','16 CPUs':'16 CPUs','guestvCPUs':'guest vCPUs','161GiB':'161 GiB','24GiB':'24 GiB','CUDA13.4':'CUDA 13.4','driver615':'driver 615','TopologyPHB':'Topology PHB','PHB topology':'PHB topology','TopologyPHB':'Topology PHB','TopographyPHB':'Topography PHB','TopologypHB':'Topology PHB','sm89':'sm_89','Q432K':'Q4 32K','Q4128K':'Q4 128K','IQ3_S32K':'IQ3_S 32K','IQ3_S128K':'IQ3_S 128K','both16':'both 16','all16':'all 16','CPU0':'CPU 0','GPU0':'GPU 0','GPU1':'GPU 1','CPU-only':'CPU-only','realCPU':'real CPU','activeCPU':'active CPU','CPUfallback':'CPU fallback','mapped/nonlocalGPU':'mapped/nonlocal GPU','localVRAM':'local VRAM','4096-input/64-output':'4096-input/64-output','saved 4096':'saved 4096','greedy4096':'greedy 4096','one 4096':'one 4096','4096-output':'4096-output','4096token':'4096 token','at3788':'at 3788','stopped3788':'stopped 3788','before its B':'before its B','original Q4':'original Q4','valid Q4':'valid Q4','saved code 32K':'saved code 32K','savedv1/v2':'saved v1/v2','variant1':'variant 1','PCIefraction0.28':'PCIe fraction 0.28','15poolworkers':'15 pool workers','pool-workers=15':'pool-workers=15','MTPspec4/minp0.5':'MTP spec=4/min-p=0.5','MTPspec4':'MTP spec=4','INT8KV':'INT8 KV','KV-resident=32768where':'KV-resident=32768 where','KV-resident=32768':'KV-resident=32768','prefillauto':'prefill=auto','KV residency is':'KV residency is','decode bounds':'decode bounds','nativeDONE':'native DONE','nativeQUIT':'native QUIT','owned-groupSIGTERM':'owned-group SIGTERM','groupSIGTERM':'group SIGTERM','groupSIGINT':'group SIGINT','later pairs signal':'later pairs signal','worker spin/sleep':'worker spin/sleep','1Hz':'1 Hz','independentN':'independent N','smallN':'small N','SmallN':'Small N','all2^N':'all 2^N','Bootstrap:20000':'Bootstrap: 20000','seed921100':'seed 921100','unit; tokens':'unit; tokens','exactly100':'exactly 100','exactly`100`':'exactly `100`','source82':'source 82','10–12pairs':'10–12 pairs','Minimum10/maximum12':'Minimum 10/maximum 12','two-replacement':'two-replacement','/proc':'/proc'}
 for a,b in replacements.items():text=text.replace(a,b)
 return text.replace('GGML pin`','GGML pin `').replace('Limitations: 10–12 pairs','Limitations: 12 pairs')
def main():
 s=run.load(C/'summary.json');i=run.load(C/'interpretation.json');p=run.load(C/'protocol.json');prov=run.load(C/'provenance/source.json');binary=run.load(C/'provenance/binary.json');env=run.load(C/'provenance/environment-inventory.json');timing=run.load(C/'timing.json');tables=(C/'tables.md').read_text();rows=list(csv.DictReader((C/'pairs.csv').open()));requests=list(csv.DictReader((C/'requests.csv').open()))
 assert all(v['valid_pairs']>=10 for v in s['cells'].values());assert len(s['cells'])==4
 label=i['decision_label'];assert label in ['SUPPORTS_LOWER_DEFAULT','SUPPORTS_ADAPTIVE_OR_PER_PHASE_POLICY','KEEP_20MS_DEFAULT','MIXED_NEEDS_MORE_DATA','INCONCLUSIVE']
 elapsed=time.monotonic()-timing['start_monotonic'];end=datetime.datetime.now(datetime.timezone.utc).isoformat()
 out=['# Strata issue921: default20ms versus 100µs pool spin','',i['lead'],'',f"Campaign started **{timing['start_utc']}**; monotonic start **{timing['start_monotonic']:.2f}s**. Absolute deadline **{timing['deadline_utc']}**; substantial-start cutoff **{timing['measurement_cutoff_utc']}**. Report rendered **{end}**, elapsed **{elapsed/3600:.3f}h**. Immutable timing file: `timing.json`.",'','## Source and binary','',f"Latest release at start was **v0.1.40.1**, source **{prov['sha']}**. Release notes say Python/server fixes only, unchanged engine. Local `git diff v0.1.40 v0.1.40.1 -- src include CMakeLists.txt cmake third_party` is empty. v0.1.40 source is {prov['v0.1.40_sha']}. Clean detached upstream clone; no native changes. The same binary served both arms: `{binary['binary_path']}`, SHA256 **{binary['binary_sha256']}**.",'',f"GGML/llama.cpp pin: **{prov['llama_ggml_pin']}**, downloaded using `gh api` and preserved as a hashed tarball. Compiler/toolkit/build commands, CMake cache, compile commands and full build log are retained. Release build, LinuxCUDA, sm89, native CPU features, static GGML, GGML OpenMP off, optional HIPMMQ off, native tests off. CMake defaults otherwise unchanged. CUDA runtime **{binary['cuda_runtime_version']}**. Compiler: `{env['gcc']['stdout'].splitlines()[0]}`. Toolkit: `{env['cuda']['stdout'].splitlines()[-1]}`. Python dependencies are frozen in the environment inventory.",'','The source still defines `kSpinBeforeSleep{20}` in `include/strata/kernels/cpu/pool.hpp:214`; `src/kernels/cpu/pool.cpp:437` reads `STRATA_POOL_SPIN_US` as microseconds. A uses the real default with the variable absent; B sets exactly100. Every actual native environment was checked and hashed by key; the spin key was the only within-pair difference. PR #949 was closed/unmerged at start, and no pool-tasks option is present in the released native source. No task-granularity tuning or residency patches.','', '## Hardware and scope','','One physical machine: **2×RTX4090 24GiB**, **Ryzen97950X3D**, **16 guest vCPUs**, approximately 161GiB guest RAM, no swap, KVM virtualization. NVIDIA driver615.71.09; CUDA13.4 runtime/toolkit. TopologyPHB; CUDA peer access unavailable in both directions. Guest-visible PCIe is x8 on both GPUs: idle sysfs reports 2.5 GT/s, with maximum 16 GT/s x16 capability; measured decode samples report Gen4 x8. Complete topology, negotiation and clocks are retained in inventory and per-phase telemetry. Native main thread is pinned by Strata to CPU 0; all16 CPUs are available to the guest, and this campaign did not change affinity, clocks, power limits, governor, VM or host settings. Worker behavior is the released default. Kernel: `'+env['uname']['stdout'].strip()+'`.','','Only expert-pool demand regimes differ: IQ3_S K25 versus UD-Q4_K_XL K24. Both are on this same GPU-heavy platform. We do not claim validation on a second machine, a CPU-only system, or a less GPU-resident platform.','', '## Frozen protocol and workload eligibility','','Each cell targets 12 valid adjacent A/B pairs, with sixAB/sixBA, and 2 AB/2 BA in each family. Seed 92110020261006 plus cell index. First 10 have fiveAB/fiveBA and code/math/prose 4/3/3; full12 have 4/4/4. The fixed round-robin cell order is IQ3_S32K, Q432K, IQ3_S128K, Q4128K for each pair number; the paired arms always run adjacently. Exact orders are saved before measurement. Pair is the experimental unit.','','Each arm: verify idle GPUs and exact identities/settings; launch a fresh server; verify resolved native config/environment/capacity; identical saved 4096-input/64-output warmup; one greedy4096-output measured request; lightweight telemetry; stop owned server/engine; verify no residual owned/GPU jobs. Fresh processes prevent inherited adaptive-tier history. Same max-context=32768 or 131072, PCIe fraction=0.28, pool-workers=15, MTPspec4/minp0.5, INT8KV, requested KV-resident=32768, prefillauto, suffix lookup off, prompt cache/reuse off, serial execution. Effective KV residency is recorded separately: in 32K, the engine reports 0 because the requested residency bound is not needed; 128K resolves it normally. No hidden K/MTP/worker/PCIe changes.','','Payloads reuse the frozen E026 real repository, numerical-library and RFC source families, with three saved nonce variants per family/context; the fourth repetition reuses variant1. Actual service-rendered input arrays and output arrays are retained, with hashes. This design repeats fixed corpora and does not represent a random sample of all code/math/prose workloads.','','Q4 output-length qualification: the original saved code 32K variant1 naturally stopped at3788 before any B request. The entire original pair was objectively invalidated under the predeclared 4096 criterion and remains preserved. A common book-length instruction was then appended to **all** Q4 measured families, profiles and variants, with no source-text trim or sampling/config change, and frozen before any valid Q4 pair. Q4 and IQ3 therefore use slightly different completion instructions; each within-model A/B uses exactly the same IDs. No prompt was selected by 100µs gain. One of the two predeclared Q432K replacement slots was used. Ledger lists any additional objective invalidations.','','Startup/warmup/measured graph-capture messages are retained. No heavy profiling during headline requests. Built-in `STRATA_DECODE_TIMING=1` and `STRATA_SPLIT_TIMING=1` are identical in both arms. Append-only frontend ID capture performs no per-token disk I/O or timestamping; two cheap /proc snapshots delimit observed decode. The first completed IQ3 pair used owned-groupSIGTERM; later pairs signal the server first for its normal nativeQUIT path. Both members of every pair use the same shutdown path; all cleanup checks passed.','','## Primary paired results','',tables.rstrip(),'','TG/PP are native request rates; wall and TTFT are client-observed. CPU columns are per-request mean guest activeCPU during decode, excluding idle, iowait and steal; steal is reported separately. Ratios are **median of B/A within pairs**, not ratios of medians. Negative wall/CPU changes are savings. Routing table uses median request counts and a common denominator: localVRAM + CPUfallback + mapped/nonlocalGPU = all routed. Local percentages are all-demand shares, not physical capacity percentages. MTP percentages are accepted/proposed.','','## Distributions and small-sample support','','| Cell | TG paired range | TG ratio IQR (Q25–Q75) | Median paired95% bootstrap | Exact sign-flip p | AB/BA paired TG medians |','|---|---:|---:|---:|---:|---:|']
 for cell,v in s['cells'].items():
  q=v['paired']['TG'];inf=q['inference'];lo,hi=inf['bootstrap_median_ratio_percentile95'];ab=v['orders']['AB']['TG_ratio']['median'];ba=v['orders']['BA']['TG_ratio']['median']
  out.append(f"| {cell} | {pct(q['min'])} to {pct(q['max'])} | {pct(q['q25'])} to {pct(q['q75'])} | {pct(lo)} to {pct(hi)} | {inf['two_sided_exact_signflip_p']:.6f} | {pct(ab)} / {pct(ba)} |")
 out+=['','A secondary order-randomization reference preserves the actual constraints: six AB/six BA, two AB/two BA per family, and five AB/five BA in the first ten. It enumerates 108 allowed assignments of labels to observed chronological second/first log TG differences. This reference assumes a sharp no-effect null and no unmodeled cross-pair interference; OS cache, thermal and host effects can remain. It was documented in `analysis-plan-addendum.json` after the first code pairs began and before math/prose measurements, retaining the original analysis and all primary metrics. It is supporting analysis, not a replacement for medians.','']
 for cell,v in s['cells'].items():
  d=v['balanced_design_randomization']
  out.append(f"- {cell}: constrained-order two-sided reference p={d['two_sided_p']:.6f} over {d['assignments']} assignments.")
 out+=['','All raw-arm TG, wall, CPU, PP and TTFT min/max/Q25/Q75/IQR values, paired ratios and ratios of arm medians are in `summary.csv` and `summary.json`; every exact pair row is in `pairs.csv`. The TG sign-flip test enumerates all2^N sign assignments of log(B/A), using absolute mean log-ratio and a two-sided tail. Its null requires exchangeable paired log differences; counterbalanced temporal order reduces but cannot eliminate drift. Bootstrap:20000 paired resamples, percentile 95%, fixed seed921100 plus cell index. SmallN, repeated fixed corpora, and possible temporal dependence limit interpretation. No token or telemetry sample is treated as an independent observation. Medians and signs are primary; p-values are supporting description, not a binary default-setting decision.','','## CPU demand, trajectory and system drift','',i['cpu_demand_analysis'],'',i['trajectory_analysis'],'',i['drift_analysis'],'','| Cell | CPU steal median A/B | CPU steal range A/B | CPU experts/layer-window A/B | CPU entries/layer-window A/B |','|---|---:|---:|---:|---:|']
 for cell,v in s['cells'].items():
  d=v['routing'];med=lambda k:'/'.join(f"{d[k][a]['median']:.3f}" for a in ['A','B']);ranges='/'.join(f"{d['decode_cpu_steal_pct'][a]['min']:.3f}–{d['decode_cpu_steal_pct'][a]['max']:.3f}" for a in ['A','B'])
  out.append(f"| {cell} | {med('decode_cpu_steal_pct')}% | {ranges}% | {med('cpu_experts_per_layer_window')} | {med('cpu_entries_per_layer_window')} |")
 out+=['','| Cell | Native process CPU median A/B | Native CPU section ms/window A/B | Native host section ms/window A/B | Median paired CPU-section change |','|---|---:|---:|---:|---:|']
 for cell,v in s['cells'].items():
  rs=[r for r in rows if r['cell']==cell];ratios=[float(r['CPU_completion_ms_per_window_B'])/float(r['CPU_completion_ms_per_window_A']) for r in rs]
  process='/'.join(f"{v['arm']['process_CPU'][a]['median']:.2f}%" for a in ['A','B'])
  cpu='/'.join(f"{v['routing']['CPU_completion_ms_per_window'][a]['median']:.3f}" for a in ['A','B'])
  host='/'.join(f"{v['routing']['pool_plus_plan_ms_per_window'][a]['median']:.3f}" for a in ['A','B'])
  out.append(f"| {cell} | {process} | {cpu} | {host} | {pct(statistics.median(ratios))} |")
 out+=['','Native process CPU uses `/proc/PID/stat` user+system tick differences divided by observed decode wall time and 16 vCPUs. Guest active CPU uses aggregate `/proc/stat` busy/total tick differences, with steal separate. These are separate guest accounting estimates, not quantities to add. The native CPU section is generally longer with 100 µs while total TG improves; this identifies an aggregate coordination/execution tradeoff, without isolating its cause.']
 out+=['','MTP/routing parity counts and first output-divergence indices are in the audit/pair files. The repeated variant 1 checks compare A-against-A and B-against-B without extra reruns; `summary.json` lists them. For identical outputs and routing/MTP counters, timing differences cannot be explained by a changed generated trajectory. Any divergent pairs remain in the primary application-level free-generation analysis, with no correctness claim inferred from unequal text.','','No exact per-worker spin/sleep counters are exposed. The retained CPU_completion_ms_per_window field is the native CPU dispatch/completion section plus remote/peer finish paths, normalized by verify windows. Its source definitions are preserved in provenance/native-cpu-timing-definition.txt and provenance/native-decode-timing-definition.txt. It does not isolate wake-up cost; overlapping stage timers are not additive. CPU utilization alone is not evidence of useful expert work; normal fallback entries and per-layer-window demand counters provide the workload measure. Mapped RAM versus remote GPU subcounts are aggregated where the released counter does not separate them. Graph captures are observed messages, not exhaustive CUDA graph-state instrumentation.','','## GPU and memory telemetry','','| Cell | Arm | GPU0 decode util/power/VRAM | GPU1 decode util/power/VRAM | GPU0/GPU1 prefill util | Native RSS | Guest RAM |','|---|---|---:|---:|---:|---:|---:|']
 for cell,v in s['cells'].items():
  for arm in ['A','B']:
   rs=[r for r in requests if r['cell']==cell and r['arm']==arm]
   def med(k):
    xs=[float(r[k]) for r in rs if r.get(k) not in (None,'','None')];return statistics.median(xs) if xs else math.nan
   g=lambda n:f"{med(f'decode_gpu{n}_util_pct'):.1f}%/{med(f'decode_gpu{n}_power_w'):.1f}W/{med(f'decode_gpu{n}_vram_mib'):.0f}MiB"
   out.append(f"| {cell} | {arm} | {g(0)} | {g(1)} | {med('prefill_gpu0_util_pct'):.1f}%/{med('prefill_gpu1_util_pct'):.1f}% | {med('decode_native_rss_mean_gib'):.1f}GiB | {med('decode_ram_mean_gib'):.1f}GiB |")
 out+=['','These are medians of each request\'s mean 1 Hz phase samples, with samples wholly inside observed phase bounds. Request means, clocks, temperatures, power, VRAM, PCIe widths/generations and RSS/RAM/swap are in `requests.csv`; full raw samples, event flags and PSI remain in telemetry. Prefill bounds extend to the first observed native output token; decode bounds run from that token through nativeDONE, omitting the first-token work from CPU integration. Native decode timing remains the primary TG clock. GPU utilization sampling does not resolve individual kernels. No GPU power, clock or governor settings were changed. The installed CUDA 13.4 NVML header labels observed clock-event bit 0x400 as reliability policy limiting clocks; the definitions and raw flags are preserved. This does not identify the host policy or prove a cause of a paired timing difference.','','## Figures','','[Paired throughput and CPU changes](figures/paired-results.png); [CPU demand relationship](figures/cpu-demand.png). Exportable SVG/PDF versions are in `figures/`.','','## Required interpretation','']
 assert len(i['answers'])==15
 for n,item in enumerate(i['answers'],1):out.append(f"{n}. **{item['question']}** {item['answer']}\n")
 out+=['## Prefill and first-token results','','| Cell | PP median A/B (tok/s) | Median paired PP change | TTFT median A/B (s) | Median paired TTFT change |','|---|---:|---:|---:|---:|']
 for cell,v in s['cells'].items():
  pp=v['arm']['PP'];tt=v['arm']['TTFT']
  out.append(f"| {cell} | {pp['A']['median']:.1f}/{pp['B']['median']:.1f} | {pct(v['paired']['PP']['median'])} | {tt['A']['median']:.3f}/{tt['B']['median']:.3f} | {pct(v['paired']['TTFT']['median'])} |")
 out+=['','PP and TTFT are separate outcomes. The total request wall includes prompt rendering/prefill and decode; a TG gain need not yield an equal wall-time gain at 128K. Family-level PP/TTFT distributions are in the JSON. No per-phase spin setting was tested.','', '## Reproducibility and exclusions','',f"Valid A/B pairs: **{s['valid_pair_total']}**. Bit-identical outputs: **{s['identical_pair_total']}/{s['valid_pair_total']}**. Objective invalidated pairs: **{len(s['invalid_pairs'])}**. Every attempted original/replacement directory is preserved; no timing- or trajectory-based exclusions. `invalid-pair-ledger.json` gives reasons, evidence hashes and replacement links. Minimum10/maximum12 per cell and the two-replacement bound are audited.",'','`scripts/analyze.py --require-complete` regenerates statistics and tables from raw arms. `scripts/render_report.py` creates this report and the unposted comment from those same tables and frozen interpretation. `scripts/audit.py` verifies binary/source/full model hashes, input/output IDs, counts/orders/families, all actual environments/configs, exclusions, serial execution, owned cleanup, reporting deadline and shared table text. See `reproduce.md` for one-cell/full-campaign commands. Initial and repaired runner copies, all savedv1/v2 payloads, frozen orders, build/source/environment provenance, raw streams/logs/telemetry, exact input/output arrays, summary CSV/JSON, script versions and final audit are preserved. No push, PR or GitHub posting.','','Evidence summary: '+i['decision_reason'],'',label]
 (C/'report.md').write_text(prose_spaces('\n'.join(out))+'\n')
 primary=tables.split('\n\n')[0]
 text=["Thanks, Niko, for specifying the interleaved 10+pair/median protocol. I ran the requested default-spin comparison on the released 0.1.40-generation engine, keeping `STRATA_POOL_SPIN_US` genuinely absent for A and setting exactly`100` for B.",'',f"**Source:** Strata **v0.1.40.1**, `{prov['sha']}`. It was the latest release at campaign start; its native engine/build tree is byte-identical to v0.1.40. I built one clean LinuxCUDA Release binary (sm89, GGMLpin`{prov['llama_ggml_pin']}`) and used it for both arms. BinarySHA256: `{binary['binary_sha256']}`. Source confirms the 20ms default and the existing microsecond override. No residency research patches, `--pool-tasks`, PR #949 combination, or other spin values.",'',"**Hardware:** one dualRTX4090 24GiB / Ryzen97950X3D KVM machine, 16guestvCPUs, approximately 161GiB RAM, no swap; driver615.71.09, CUDA13.4. PHB topology, CUDApeer access unavailable. Clocks, power limits, affinity, governor and VM/host settings were unchanged.",'',"**Regimes:** IQ3_S K25 is highly resident by routed demand and CPU-light; UD-Q4_K_XL K24 has roughly 47% physical expert capacity and materially more realCPU fallback work. These are two workload regimes on the same GPU-heavy machine, not two independent machines. Both keep PCIefraction0.28, 15poolworkers, MTPspec4/minp0.5, INT8KV, KV-resident=32768where applicable, prefillauto, suffix lookup/reuse off, greedy serial execution.",'',f"**Design:** {s['valid_pair_total']} valid adjacent A/B pairs across the four cells below. Each12-pair cell has sixAB/sixBA, balanced 2/2 within code/math/prose, with fixed saved order and seed. Each arm uses a fresh server, the same 4096-input/64-output warmup, then exactly one 4096-output request. Actual native environments, command lines, hashes, capacities and input IDs were checked; only the spin environment key differs within each pair. Saved independent repository/numerical/RFC workloads were reused, with four pairs per family. The fourth repeats a saved variant. No timing-based prompt selection.",'',primary,'',"TG and wall changes are **medians of within-pair B/A ratios**, not ratios of arm medians. CPU is mean guest activeCPU during decode, excluding steal, then paired in the same way. Exact pair rows, raw-arm ranges/IQRs, paired ranges, AB/BA splits, seeded paired-median bootstrap intervals and exact sign-flip tests on log TG ratios are retained. The pair is the unit; tokens and 1 Hz telemetry are not independentN.",'',i['github_results'],'',i['github_correctness'],'',"One eligibility failure was preserved: the original Q4 code 32K request naturally stopped at3788 tokens, before its B arm. I froze the same stronger book-length instruction across all Q4 families/contexts/variants before any valid Q4 pair, retained the source text, and used the predeclared replacement slot. IQ3 inputs are unchanged. This is a declared output-length exclusion, not a performance exclusion. All original and replacement attempts remain in the ledger/raw artifacts.",'',i['github_drift'],'',"The CPU demand comparison uses normal fallback entries and CPU experts/entries per layer-window, not utilization alone. Exact worker spin/sleep counters and isolated wake-up latency are unavailable on the released headline binary. Aggregate CPU completion timing cannot establish the wake-up mechanism by itself; I did not add heavy profiling or a spin sweep.",'',i['github_conclusion'],'',"Limitations: 10–12pairs per cell on one physical dual-4090 / 7950X3D VM, fixed repeated corpora, model/context-specific greedy free generation, and residual host scheduling/thermal drift. Family results have only four pairs each. This does not establish cross-machine generality, safety on CPU-heavy hardware, or a universal 100µs default. It provides the requested paired medians for these two expert-pool demand regimes. The full report, reproducibility commands, hashes, logs, token arrays and telemetry are preserved locally; this comment has not been posted."]
 (C/'github-issue-921-comment.md').write_text(prose_spaces('\n'.join(text))+'\n')
 print(json.dumps({'rendered':end,'decision':label,'comment_words':len(' '.join(text).split()),'elapsed_hours':elapsed/3600},indent=2))
if __name__=='__main__':main()
